const withGaps = createChatOrchestrator(
  createMockProvider([
    [
      {type: 'tool_use', toolCall: {id: '1', name: 'lookup', input: {}}},
      {type: 'stop', stopReason: 'tool_use', usage: {inputTokens: 5, outputTokens: 2, totalTokens: 7}},
    ],
    [
      {type: 'tool_use', toolCall: {id: '2', name: 'lookup', input: {}}},
      {type: 'stop', stopReason: 'tool_use'},
    ],
    [
      {type: 'text', text: 'Done'},
      {type: 'stop', stopReason: 'end_turn', usage: {inputTokens: 13, outputTokens: 8, totalTokens: 21}},
    ],
  ]),
  promptBuilder,
  registry,
  {hooks}
);

const withoutUsage = createChatOrchestrator(
  createMockProvider([
    [
      {type: 'text', text: 'No usage here'},
      {type: 'stop', stopReason: 'end_turn'},
    ],
  ]),
  promptBuilder,
  undefined,
  {hooks}
);

await withGaps.processMessage(session());
await withoutUsage.processMessage(session());

expect(reports).toEqual([{inputTokens: 18, outputTokens: 10, totalTokens: 28}, undefined]);

